#!/usr/bin/env python3
import subprocess
import os

# Download the file using curl
cmd = [
    'curl',
    '-u', 'theagentcompany:theagentcompany',
    '-O',
    'http://the-agent-company.com:8092/remote.php/dav/files/theagentcompany/Documents/command.txt'
]

try:
    result = subprocess.run(cmd, cwd='/tmp/mcp-workspace', capture_output=True, text=True)
    if result.returncode == 0:
        print("File downloaded successfully to /tmp/mcp-workspace/command.txt")
    else:
        print(f"Error: {result.stderr}")
except Exception as e:
    print(f"Exception: {e}")

